        Action("−",()=>canvas.Zoom(-2));Action("+",()=>canvas.Zoom(2));bar.Controls.Add(play);play.Click+=(_,_)=>Guard(()=>{testing=!testing;playerX=current.SpawnX;playerY=current.SpawnY;play.Text=testing?"Stop walk-test":"Walk-test";canvas.Focus();RefreshAll(false);});
