    void Guard(Action a){try{a();}catch(Exception e){MessageBox.Show(this,e.Message,"Map Studio",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    bool ConfirmDiscard()=>!dirty||MessageBox.Show(this,"Discard unsaved changes?","Map Studio",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;
    void PushUndo(){undo.Push(pack.Clone());redo.Clear();if(undo.Count>30){var keep=undo.Take(30).Reverse().ToArray();undo.Clear();foreach(var p in keep)undo.Push(p);}}
    void Changed(){dirty=true;RefreshAll(false);}
    void History(Stack<ContentPack> source,Stack<ContentPack> dest){if(source.Count==0)return;var id=current.Id;dest.Push(pack.Clone());pack=source.Pop();current=pack.Maps.FirstOrDefault(m=>m.Id==id)??pack.Maps[0];canvas.Selected=null;testing=false;dirty=true;RefreshAll();}
    void RefreshAll(bool list=true){refreshing=true;if(list){maps.Items.Clear();maps.Items.AddRange(pack.Maps.Cast<object>().ToArray());maps.SelectedItem=current;properties.SelectedObject=new MapDetails(current);}RefreshScene();Text=$"{(dirty?"* ":"")}{pack.Name} — Inverna Map Studio";status.Text=$"  {current.Name}  •  {current.Width} × {current.Height} tiles  •  {current.Objects.Count} objects  •  {(testing?"Walk-test: arrows move, Enter interacts. This tests editor collision only.":"Project and pack export are local.")}";refreshing=false;canvas.Invalidate();}
    void Open(bool imported){if(!ConfirmDiscard())return;using var d=new OpenFileDialog{Filter=imported?"Inverna content pack|*.ptpack":"Inverna project|*.inverna.json;*.json"};if(d.ShowDialog()!=DialogResult.OK)return;var next=imported?ContentPack.Import(d.FileName):ContentPack.LoadProject(d.FileName);pack=next;current=pack.Maps[0];file=imported?null:d.FileName;undo.Clear();redo.Clear();dirty=false;testing=false;canvas.Selected=null;canvas.ResetView();RefreshAll();}
    void Save(){if(file==null){using var d=new SaveFileDialog{Filter="Inverna project|*.inverna.json",FileName=pack.Id+".inverna.json"};if(d.ShowDialog()!=DialogResult.OK)return;file=d.FileName;}pack.SaveProject(file);dirty=false;RefreshAll(false);}
    void Export(){using var d=new SaveFileDialog{Filter="Inverna content pack|*.ptpack",FileName=pack.Id+"-"+pack.Version+".ptpack"};if(d.ShowDialog()!=DialogResult.OK)return;pack.Export(d.FileName);status.Text="  Exported "+d.FileName+" • Native game adapter still required.";}
    void AddMap(){using var d=new Form{Text="Add map",Width=340,Height=260,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false};var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),FlowDirection=FlowDirection.TopDown,WrapContents=false};var name=new TextBox{Text="district-"+(pack.Maps.Count+1),Width=280};var width=new NumericUpDown{Minimum=8,Maximum=128,Value=32};var height=new NumericUpDown{Minimum=8,Maximum=128,Value=32};var ok=new Button{Text="Create map",DialogResult=DialogResult.OK,AutoSize=true};panel.Controls.AddRange([new Label{Text="Map ID (lowercase, unique)",AutoSize=true},name,new Label{Text="Width / height in tiles",AutoSize=true},width,height,ok]);d.Controls.Add(panel);d.AcceptButton=ok;if(d.ShowDialog(this)!=DialogResult.OK)return;if(!System.Text.RegularExpressions.Regex.IsMatch(name.Text,"^[a-z0-9][a-z0-9-]{0,47}$")||pack.Maps.Any(m=>m.Id==name.Text))throw new Exception("Choose a valid, unique map ID.");PushUndo();current=new(){Id=name.Text,Name=name.Text,Width=(int)width.Value,Height=(int)height.Value,Terrain=new byte[(int)(width.Value*height.Value)],Collision=new byte[(int)(width.Value*height.Value)],SpawnX=2,SpawnY=2};pack.Maps.Add(current);dirty=true;RefreshAll();}
    void KeysDown(object? sender,KeyEventArgs e){if(properties.ContainsFocus)return;if(e.Control&&e.KeyCode==Keys.S){Guard(Save);e.SuppressKeyPress=true;return;}if(e.Control&&e.KeyCode==Keys.Z){History(undo,redo);e.SuppressKeyPress=true;return;}if(e.Control&&e.KeyCode==Keys.Y){History(redo,undo);e.SuppressKeyPress=true;return;}if(testing){int x=playerX,y=playerY;if(e.KeyCode==Keys.Left)x--;if(e.KeyCode==Keys.Right)x++;if(e.KeyCode==Keys.Up)y--;if(e.KeyCode==Keys.Down)y++;if(current.InBounds(x,y)&&current.Collision[y*current.Width+x]==0&&!current.Objects.Any(o=>o.Contains(x,y)&&o.Solid&&o.Kind!="warp")){playerX=x;playerY=y;var warp=current.Objects.FirstOrDefault(o=>o.Kind=="warp"&&o.X==x&&o.Y==y);if(warp!=null){var dest=pack.Maps.FirstOrDefault(m=>m.Id==warp.Destination);if(dest!=null&&dest.InBounds(warp.DestinationX,warp.DestinationY)&&dest.Collision[warp.DestinationY*dest.Width+warp.DestinationX]==0){current=dest;playerX=warp.DestinationX;playerY=warp.DestinationY;RefreshAll();}}}if(e.KeyCode==Keys.Enter){var o=current.Objects.FirstOrDefault(o=>(o.Kind=="npc"||o.Kind=="sign")&&Math.Abs(o.X-playerX)+Math.Abs(o.Y-playerY)<=1);if(o!=null)MessageBox.Show(this,o.Text,o.Id);}canvas.Invalidate();e.SuppressKeyPress=true;return;}if(e.KeyCode==Keys.Delete&&canvas.Selected!=null){PushUndo();current.Objects.Remove(canvas.Selected);canvas.Selected=null;properties.SelectedObject=null;Changed();}}
    sealed class PackDetails(ContentPack pack){public string Name{get=>pack.Name;set=>pack.Name=value;}public string Id{get=>pack.Id;set=>pack.Id=value;}public string Version{get=>pack.Version;set=>pack.Version=value;}public string Author{get=>pack.Author;set=>pack.Author=value;}[System.ComponentModel.TypeConverter(typeof(GameTargetConverter))]public string Target{get=>pack.Target;set=>pack.Target=value;}}
    sealed class MapDetails(Map map){public string Name {get=>map.Name;set=>map.Name=value;}[System.ComponentModel.ReadOnly(true)]public string Id=>map.Id;[System.ComponentModel.ReadOnly(true)]public int Width=>map.Width;[System.ComponentModel.ReadOnly(true)]public int Height=>map.Height;public MapEnvironment Environment=>map.Environment;public int SpawnX{get=>map.SpawnX;set=>map.SpawnX=value;}public int SpawnY{get=>map.SpawnY;set=>map.SpawnY=value;}}
    sealed partial class MapCanvas:Control
    {
        readonly Editor owner;float size=22;PointF origin=new(35,35);bool painting,panning;Point previous;public MapObject? Selected;
        static readonly Color[] Tiles=[Color.FromArgb(155,168,181),Color.FromArgb(69,82,99),Color.FromArgb(73,132,91),Color.FromArgb(51,119,160),Color.FromArgb(160,119,74),Color.FromArgb(111,113,135)];
        public MapCanvas(Editor editor){owner=editor;DoubleBuffered=true;BackColor=Color.FromArgb(22,30,43);TabStop=true;StartAnimation();MouseDown+=Down;MouseMove+=MoveMouse;MouseUp+=(_,_)=>{painting=false;panning=false;Capture=false;};MouseWheel+=(_,e)=>Zoom(e.Delta>0?2:-2);}
        public void Zoom(int delta){size=Math.Clamp(size+delta,6,52);Invalidate();}public void ResetView(){origin=new(35,35);Invalidate();}
        Point Cell(Point p)=>new((int)Math.Floor((p.X-origin.X)/size),(int)Math.Floor((p.Y-origin.Y)/size));
        void Down(object? sender,MouseEventArgs e){Focus();if(e.Button==MouseButtons.Middle){panning=true;previous=e.Location;Capture=true;return;}if(e.Button!=MouseButtons.Left||owner.testing)return;var p=Cell(e.Location);if(!owner.current.InBounds(p.X,p.Y))return;owner.PushUndo();painting=true;Capture=true;if(owner.tool.SelectedIndex==0){Selected=owner.current.Objects.LastOrDefault(o=>o.Contains(p.X,p.Y));owner.properties.SelectedObject=Selected;Invalidate();return;}Apply(p,true);}
        void MoveMouse(object? sender,MouseEventArgs e){if(panning){origin.X+=e.X-previous.X;origin.Y+=e.Y-previous.Y;previous=e.Location;Invalidate();return;}if(!painting||owner.testing)return;var p=Cell(e.Location);if(!owner.current.InBounds(p.X,p.Y))return;if(owner.tool.SelectedIndex==0&&Selected!=null){Selected.X=p.X;Selected.Y=p.Y;owner.properties.Refresh();owner.Changed();}else Apply(p,false);}
        void Apply(Point p,bool first){var map=owner.current;int i=p.Y*map.Width+p.X;switch(owner.tool.SelectedIndex){case 1:map.Terrain[i]=(byte)owner.terrain.SelectedIndex;break;case 2:map.Collision[i]=1;break;case 3:map.Collision[i]=0;break;case 4:if(!first)return;var kind=owner.kind.Text;Selected=new(){Id=kind+"-"+Guid.NewGuid().ToString("N")[..8],Kind=kind,X=p.X,Y=p.Y,Solid=kind is not("warp" or "effect"),Destination=kind=="warp"?map.Id:"",DestinationX=map.SpawnX,DestinationY=map.SpawnY};map.Objects.Add(Selected);owner.properties.SelectedObject=Selected;break;case 5:map.SpawnX=p.X;map.SpawnY=p.Y;break;default:return;}owner.Changed();}
        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;var m=owner.current;g.SmoothingMode=SmoothingMode.AntiAlias;for(int y=0;y<m.Height;y++)for(int x=0;x<m.Width;x++){float px=origin.X+x*size,py=origin.Y+y*size;if(px+size<0||py+size<0||px>Width||py>Height)continue;using var b=new SolidBrush(Tiles[Math.Min((int)m.Terrain[y*m.Width+x],5)]);g.FillRectangle(b,px,py,size,size);if(size>=12)g.DrawRectangle(Pens.DimGray,px,py,size,size);if(owner.collision.Checked&&m.Collision[y*m.Width+x]!=0){using var blocked=new SolidBrush(Color.FromArgb(125,230,57,76));g.FillRectangle(blocked,px,py,size,size);}}DrawObjects(g);float sx=origin.X+(m.SpawnX+.5f)*size,sy=origin.Y+(m.SpawnY+.5f)*size;g.DrawLine(Pens.White,sx-6,sy,sx+6,sy);g.DrawLine(Pens.White,sx,sy-6,sx,sy+6);if(owner.testing){g.FillEllipse(Brushes.White,origin.X+(owner.playerX+.2f)*size,origin.Y+(owner.playerY+.2f)*size,size*.6f,size*.6f);}g.DrawString("N ↑     Scene preview • native asset loader pending",Font,Brushes.White,8,8);}
    }
